import numpy as np
import torch
import math
import base64
import io
from dataclasses import dataclass, field
from typing import List, Optional, Tuple, Dict, Any


# ---- Dataclasses ----

@dataclass
class PlanetState:
    planet_id: int
    owner: int
    ship_count: int
    production: int
    x: float
    y: float

@dataclass
class FleetState:
    owner: int
    ship_count: int
    source_id: int
    target_id: int
    turns_remaining: int

@dataclass
class GameState:
    turn: int
    max_turns: int
    planets: List[PlanetState]
    fleets: List[FleetState]


# ---- Feature Extraction ----

def encode_turn(obs, candidate_count=8):
    """Convert observation dict to feature tensors."""
    game_state = GameState(
        turn=obs.get("turn", 0),
        max_turns=obs.get("max_turns", 100),
        planets=[PlanetState(**p) for p in obs.get("planets", [])],
        fleets=[FleetState(**f) for f in obs.get("fleets", [])]
    )

    my_id = obs.get("player_id", 0)
    planets = game_state.planets
    fleets = game_state.fleets

    planet_by_id = {p.planet_id: p for p in planets}
    my_planets = [p for p in planets if p.owner == my_id]

    self_features_list = []
    candidate_features_list = []
    global_features_list = []
    planet_ids = []
    candidate_lists = []

    for planet in my_planets:
        total_ships = sum(p.ship_count for p in my_planets)
        total_prod = sum(p.production for p in my_planets)
        enemy_ships = sum(p.ship_count for p in planets if p.owner not in (0, my_id))
        neutral_ships = sum(p.ship_count for p in planets if p.owner == 0)

        self_feat = [
            planet.ship_count / 100.0,
            planet.production / 10.0,
            len(my_planets) / 20.0,
            total_ships / 500.0,
            total_prod / 50.0,
            game_state.turn / game_state.max_turns,
            enemy_ships / 500.0,
            neutral_ships / 500.0,
            len(planet_by_id) / 30.0,
            (planet.ship_count / max(total_ships, 1)) if total_ships > 0 else 0.0,
        ]
        self_features_list.append(self_feat)
        planet_ids.append(planet.planet_id)

        candidates = [p for p in planets if p.planet_id != planet.planet_id][:candidate_count]
        candidate_lists.append([c.planet_id for c in candidates])

        for cand in candidates:
            dist = math.sqrt((planet.x - cand.x)**2 + (planet.y - cand.y)**2)
            max_dist = math.sqrt(2) * 100
            cand_feat = [
                cand.planet_id / 30.0,
                cand.ship_count / 100.0,
                cand.production / 10.0,
                (cand.owner == my_id) * 1.0,
                (cand.owner == 0) * 1.0,
                (cand.owner not in (0, my_id)) * 1.0,
                dist / max_dist,
                planet.ship_count / 100.0,
                cand.production / max(planet.production, 1) if planet.production > 0 else 0.0,
                (cand.ship_count > planet.ship_count) * 1.0,
                (cand.ship_count <= planet.ship_count * 1.5) * 1.0,
                (cand.owner == 0 and cand.ship_count == 0) * 1.0,
                (cand.production >= 3) * 1.0,
            ]
            candidate_features_list.append(cand_feat)

    while len(candidate_features_list) < len(self_features_list) * candidate_count:
        candidate_features_list.append([0.0] * 13)

    for _ in my_planets:
        total_ships = sum(p.ship_count for p in my_planets)
        total_prod = sum(p.production for p in my_planets)
        enemy_ships = sum(p.ship_count for p in planets if p.owner not in (0, my_id))
        neutral_ships = sum(p.ship_count for p in planets if p.owner == 0)
        global_feat = [
            game_state.turn / game_state.max_turns,
            len(my_planets) / 20.0,
            total_ships / 500.0,
            total_prod / 50.0,
            enemy_ships / 500.0,
            neutral_ships / 500.0,
            len(planet_by_id) / 30.0,
            len(fleets) / 100.0,
        ]
        global_features_list.append(global_feat)

    candidate_mask = []
    for i in range(len(planet_ids)):
        for j in range(candidate_count):
            candidate_mask.append(1.0 if j < len(candidate_lists[i]) else 0.0)

    from collections import namedtuple
    TurnBatch = namedtuple('TurnBatch', ['self_features', 'candidate_features', 'global_features', 'candidate_mask', 'planet_ids', 'candidate_lists'])

    return TurnBatch(
        self_features=np.array(self_features_list, dtype=np.float32),
        candidate_features=np.array(candidate_features_list, dtype=np.float32),
        global_features=np.array(global_features_list, dtype=np.float32),
        candidate_mask=np.array(candidate_mask, dtype=np.float32),
        planet_ids=planet_ids,
        candidate_lists=candidate_lists,
    )


# ---- Policy Network (matches src/policy.py exactly) ----

def _mlp(input_dim: int, hidden_size: int):
    return torch.nn.Sequential(
        torch.nn.Linear(input_dim, hidden_size),
        torch.nn.ReLU(),
        torch.nn.Linear(hidden_size, hidden_size),
        torch.nn.ReLU(),
    )

class PlanetPolicy(torch.nn.Module):
    def __init__(self, self_dim, candidate_dim, global_dim, candidate_count, hidden_size=128):
        super().__init__()
        self.candidate_count = candidate_count
        self.self_encoder = _mlp(self_dim, hidden_size)
        self.candidate_encoder = _mlp(candidate_dim, hidden_size)
        self.global_encoder = _mlp(global_dim, hidden_size)
        self.target_head = torch.nn.Sequential(
            torch.nn.Linear(hidden_size * 3, hidden_size),
            torch.nn.ReLU(),
            torch.nn.Linear(hidden_size, 1),
        )
        self.value_head = torch.nn.Sequential(
            torch.nn.Linear(hidden_size * 3, hidden_size),
            torch.nn.ReLU(),
            torch.nn.Linear(hidden_size, 1),
        )

    def forward(self, self_features, candidate_features, global_features, candidate_mask):
        self_h = self.self_encoder(self_features)
        global_h = self.global_encoder(global_features)
        candidate_h = self.candidate_encoder(candidate_features)

        batch_size = self_features.shape[0]
        expanded_self = self_h.unsqueeze(1).expand(-1, self.candidate_count, -1)
        expanded_global = global_h.unsqueeze(1).expand(-1, self.candidate_count, -1)
        candidate_h_reshaped = candidate_h.view(batch_size, self.candidate_count, -1)
        joint = torch.cat([expanded_self, expanded_global, candidate_h_reshaped], dim=-1)
        logits = self.target_head(joint).squeeze(-1)
        logits = logits.masked_fill(~candidate_mask.bool(), torch.finfo(logits.dtype).min)

        pooled = candidate_h_reshaped.mean(dim=1)
        value = self.value_head(torch.cat([self_h, global_h, pooled], dim=-1)).squeeze(-1)

        return type('PolicyOutput', (), {'target_logits': logits, 'value': value})()


# ---- Kaggle Agent ----

CHECKPOINT_B64 = ""

class KaggleAgent:
    def __init__(self):
        self.candidate_count = 8
        self.policy = PlanetPolicy(
            10,
            13,
            8,
            self.candidate_count,
            128,
        )
        self._load_weights()
        self.policy.eval()

    def _load_weights(self):
        checkpoint_bytes = base64.b64decode(CHECKPOINT_B64)
        buffer = io.BytesIO(checkpoint_bytes)
        checkpoint = torch.load(buffer, map_location='cpu', weights_only=False)
        self.policy.load_state_dict(checkpoint["policy"])

    def act(self, obs):
        with torch.no_grad():
            turn_batch = encode_turn(obs, self.candidate_count)
            if turn_batch.self_features.shape[0] == 0:
                return []

            self_features = torch.from_numpy(turn_batch.self_features)
            candidate_features = torch.from_numpy(turn_batch.candidate_features)
            global_features = torch.from_numpy(turn_batch.global_features)
            candidate_mask = torch.from_numpy(turn_batch.candidate_mask).bool()

            outputs = self.policy(self_features, candidate_features, global_features, candidate_mask)
            logits = outputs.target_logits
            masked_logits = logits.masked_fill(~candidate_mask, float('-inf'))
            action_indices = torch.argmax(masked_logits, dim=-1)

            moves = []
            for i, (planet_id, target_idx) in enumerate(zip(turn_batch.planet_ids, action_indices)):
                target_idx = target_idx.item()
                if target_idx < len(turn_batch.candidate_lists[i]):
                    target_id = turn_batch.candidate_lists[i][target_idx]
                    moves.append({"planet_id": planet_id, "target_id": target_id})
            return moves


# ---- Global act function (required by Kaggle) ----

_agent = None

def get_agent():
    global _agent
    if _agent is None:
        _agent = KaggleAgent()
    return _agent

def act(obs):
    agent = get_agent()
    return agent.act(obs)


